def fill_diagonal(output, r1, c1, r2, c2, value):
    """Fill cells along the line between (r1,c1) and (r2,c2) with the given value."""
    h, w = len(output), len(output[0])

    step_r = 1 if r2 >= r1 else -1
    step_c = 1 if c2 >= c1 else -1

