def fill_diagonal_full(grid, start_r, start_c, value, diagonal_type='main'):
    """Fill the entire diagonal (main or anti) through a point with the given value."""
    h, w = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    if diagonal_type == 'main':  # Fill r-c = constant
        target_diff = start_r - start_c
        mask = [d for d in range(1 - w, h) if -w < d < h]
        for (r, c) in sorted(mask, key=lambda x: x[0]):
            if 0 <= r < h and 0 <= c < w and r - c == target_diff:
                output[r][c] = value
    elif diagonal_type == 'anti':  # Fill r+c = constant
        target_sum = start_r + start_c
        mask = [d for d in range(w - 1, h + w - 1)]
        for (r, c) in sorted(mask, key=lambda x: x[0]):
            if 0 <= r < h and 0 <= c < w and r + c == target_sum:
