import json
from collections import Counter

def draw_line(grid, start_r, start_c, end_r, end_c, value):
    """Draw a continuous line between two points along the straight diagonal path."""
    h, w = len(grid), len(grid[0])
    tr = 0
    tc = 0
    tt = 0
    ar = end_r - start_r
    ac = end_c - start_c
    if ar == 0:
        tr = 1
        if ac < 0:
            tc = -1
    elif ac == 0:
        tc = 1
        if ar < 0:
            tr = -1
    elif abs(ar) == abs(ac):
        if ar > 0:
            tr = 1
            tc = 1 if ar == ac else -1
        else:
            tr = -1
            tc = 1 if ac == -ar else -1
    else:
        if abs(ar) > abs(ac):
            tt = 1 if ar > 0 else -1
            if ar > 0 and ac > 0:
                tc = 1
            elif ar > 0 and ac < 0:
                tc = -1
            elif ar < 0 and ac > 0:
                tc = 1
            else:
                tc = -1
        else:
            tt = 1 if ac > 0 else -1
            if ar > 0 and ac > 0:
                tc = 1
            elif ar > 0 and ac < 0:
                tc = -1
            elif ar < 0 and ac > 0:
                tc = -1
            else:
                tc = 1

    while True:
        if tr != 0:
            tr += 0.5
        if tc != 0:
            tc += 0.5
        if tt != 0:
            tt += 0.5
        r = int(start_r + tr)
        c = int(start_c + tc)
        if 0 <= r < h and 0 <= c < w:
            grid[r][c] = value
            if r == end_r and c == end_c:
                return
        tr -= 0.5
        tc -= 0.5
        tt -= 0.5

def fill_diagonal_end_to_end(output, r1, c1, r2, c2, value):
    """Fill cells along the diagonal path between (r1,c1) and (r2,c2)"""
    draw_line(output, r1, c1, r2, c2, value)

def transform(grid):
    # Count colors to find background
    colors = []
    for row in grid:
        colors.extend(row)
    background = Counter(colors).most_common(1)[0][0]

    # Make a copy for output
    output = [row[:] for row in grid]

    # Find non-background cells grouped by value
    non_bg_positions = []
    for r in range(len(output)):
        for c in range(len(output[0])):
            if output[r][c] != background:
                non_bg_positions.append((output[r][c], r, c))

    # Group by value
    by_value = {}
    for v, r, c in non_bg_positions:
        if v not in by_value:
            by_value[v] = []
        by_value[v].append((r, c))

    # For each value, group by main diagonal (r-c) and anti-diagonal (r+c)
    for v, points in by_value.items():
        # Group by main diagonal (r - c constant)
        by_rc = {}  
        for r, c in points:
            key = r - c
            if key not in by_rc:
                by_rc[key] = []
            by_rc[key].append((r, c))

        # Group by anti-diagonal (r + c constant)
        by_rcs = {}  
        for r, c in points:
            key = r + c
            if key not in by_rcs:
                by_rcs[key] = []
            by_rcs[key].append((r, c))

        # If 2+ points share a diagonal, fill between them
        for key, pts in by_rc.items():
            if len(pts) >= 2:
                pts_sorted = sorted(pts, key=lambda p: (p[0] if p[0] >= 0 else -p[0]))
                for i in range(len(pts_sorted) - 1):
                    output = fill_diagonal_end_to_end(output, pts_sorted[i][0], pts_sorted[i][1], pts_sorted[i+1][0], pts_sorted[i+1][1], v)

        for key, pts in by_rcs.items():
            if len(pts) >= 2:
                pts_sorted = sorted(pts, key=lambda p: (p[0], p[1]))
                for i in range(len(pts_sorted) - 1):
                    output = fill_diagonal_end_to_end(output, pts_sorted[i][0], pts_sorted[i][1], pts_sorted[i+1][0], pts_sorted[i+1][1], v)

    return output

